package org.brightstats.stats;
import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
public final class HigherOrderChecks {
    private static int checks;
    private static void check(boolean condition){if(!condition)throw new AssertionError("Higher-order check "+checks);checks++;}
    private static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid higher-order model accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception {
        Path output=Path.of(args[0]);Files.createDirectories(output);Gson gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();JsonArray cases=new JsonArray();
        for(int scenario=0;scenario<12;scenario++){
            int count=scenario==5?6:(scenario>=8&&scenario<10)?3:4,n=120;int[] sizes=new int[count];for(int j=0;j<count;j++)sizes[j]=scenario==5?2:2+j%2;int width=Arrays.stream(sizes).sum();double[][] data=new double[n][width];Random random=new Random(546432+scenario);
            for(double[] row:data){double a=random.nextGaussian(),b=.5*a+Math.sqrt(.75)*random.nextGaussian(),c=random.nextGaussian(),d=.4*c+Math.sqrt(.84)*random.nextGaussian();double m=.4*a+.3*b+.2*c+.1*d+.6*random.nextGaussian(),y=.6*m+.2*a+.3*c+.6*random.nextGaussian();double[] latent=scenario==5?new double[]{a,b,c,d,m,y}:scenario==6?new double[]{a,b,c,y}:(scenario>=8&&scenario<10)?new double[]{a,b,y}:new double[]{a,b,m,y};for(int block=0,column=0;block<count;block++)for(int j=0;j<sizes[block];j++)row[column++]=(.8+.1*j)*latent[block]+.25*random.nextGaussian();}
            List<PlsSem.Block> blocks=new ArrayList<>();for(int block=0,column=0;block<count;block++){int[] columns=new int[sizes[block]];for(int j=0;j<columns.length;j++)columns[j]=column++;boolean formative=scenario==2||scenario==3||scenario==11;PlsSem.Mode mode=formative&&block<2?PlsSem.Mode.B:PlsSem.Mode.A;double[] initial=null;if(scenario==4&&block==0){initial=new double[columns.length];Arrays.fill(initial,-1);}blocks.add(new PlsSem.Block("L"+block,columns,mode,initial,mode==PlsSem.Mode.A?PlsSem.MeasurementType.REFLECTIVE:PlsSem.MeasurementType.FORMATIVE));}
            List<PlsSem.Edge> edges=new ArrayList<>();if(scenario==5){for(int j=0;j<4;j++){edges.add(new PlsSem.Edge(j,4));edges.add(new PlsSem.Edge(j,5));}edges.add(new PlsSem.Edge(4,5));}else if(scenario==6){for(int j=0;j<3;j++)edges.add(new PlsSem.Edge(j,3));}else if((scenario>=8&&scenario<10)){edges.add(new PlsSem.Edge(0,2));edges.add(new PlsSem.Edge(1,2));}else{edges.addAll(List.of(new PlsSem.Edge(0,2),new PlsSem.Edge(1,2),new PlsSem.Edge(2,3),new PlsSem.Edge(0,3),new PlsSem.Edge(1,3)));}
            List<HigherOrderPls.Dimension> higher=new ArrayList<>();boolean hocFormative=scenario==1||scenario==3||scenario==4||scenario==9||scenario==11;higher.add(new HigherOrderPls.Dimension("General",new int[]{0,1},hocFormative?PlsSem.Mode.B:PlsSem.Mode.A,hocFormative?PlsSem.MeasurementType.FORMATIVE:PlsSem.MeasurementType.REFLECTIVE,scenario==4?new double[]{-1,1}:null));
            int[] retained;List<PlsSem.Edge> secondEdges;
            if(scenario==5){higher.add(new HigherOrderPls.Dimension("Other",new int[]{2,3},PlsSem.Mode.B,PlsSem.MeasurementType.FORMATIVE,null));retained=new int[]{4,5};secondEdges=List.of(new PlsSem.Edge(2,0),new PlsSem.Edge(3,0),new PlsSem.Edge(0,1),new PlsSem.Edge(2,1),new PlsSem.Edge(3,1));}
            else if(scenario==6){higher.add(new HigherOrderPls.Dimension("Other",new int[]{1,2},PlsSem.Mode.B,PlsSem.MeasurementType.FORMATIVE,null));retained=new int[]{3};secondEdges=List.of(new PlsSem.Edge(1,0),new PlsSem.Edge(2,0));}
            else if(scenario==7){retained=new int[]{3};secondEdges=List.of(new PlsSem.Edge(1,0));}
            else if((scenario>=8&&scenario<10)){retained=new int[0];secondEdges=List.of();}
            else{retained=new int[]{2,3};secondEdges=List.of(new PlsSem.Edge(2,0),new PlsSem.Edge(0,1),new PlsSem.Edge(2,1));}
            if(scenario>=10){int[] repeated=java.util.stream.IntStream.concat(Arrays.stream(blocks.get(0).columns()),Arrays.stream(blocks.get(1).columns())).toArray();blocks.add(new PlsSem.Block("General_stage1",repeated,scenario==11?PlsSem.Mode.B:PlsSem.Mode.A,null,scenario==11?PlsSem.MeasurementType.FORMATIVE:PlsSem.MeasurementType.REFLECTIVE));edges.clear();edges.addAll(scenario==11?List.of(new PlsSem.Edge(0,4),new PlsSem.Edge(1,4)):List.of(new PlsSem.Edge(4,0),new PlsSem.Edge(4,1)));edges.addAll(List.of(new PlsSem.Edge(4,2),new PlsSem.Edge(2,3),new PlsSem.Edge(4,3)));}
            var options=PlsSem.Options.defaults();var secondOptions=new PlsSem.Options(3000,1e-7,scenario%2==1?PlsSem.Weighting.FACTOR:PlsSem.Weighting.PATH);var specification=new HigherOrderPls.Specification(retained,higher,secondEdges,secondOptions);var fit=HigherOrderPls.fit(data,blocks,edges,options,specification);
            check(fit.firstStage().converged()&&fit.secondStage().converged());check(fit.observations()==n&&fit.originalColumns()==width);check(fit.secondStageBlocks().size()==retained.length+higher.size());check(fit.dimensions().size()==higher.stream().mapToInt(value->value.lowerOrder().length).sum());check(fit.warnings().size()>=4);double[][] scores=fit.firstStage().scores(),augmented=HigherOrderPls.augment(data,scores);check(augmented.length==n&&augmented[0].length==width+blocks.size());check(augmented[0][width]==scores[0][0]&&augmented[0][0]==data[0][0]);if(retained.length>0){int[] copy=specification.retained();int first=copy[0];copy[0]=99;check(specification.retained()[0]==first);}if(scenario==6)check(fit.warnings().stream().anyMatch(message->message.contains("reused")));if(scenario==7)check(fit.warnings().stream().anyMatch(message->message.contains("omitted")));if(scenario==9)check(fit.warnings().stream().anyMatch(message->message.contains("not identified")));if(scenario<6&&scenario!=5)check(!fit.specificIndirect().isEmpty());
            JsonObject item=new JsonObject();item.addProperty("id","higher-order-"+scenario);item.addProperty("approach",scenario>=10?"EMBEDDED_TWO_STAGE":"DISJOINT_TWO_STAGE");item.add("observations",gson.toJsonTree(data));item.add("blocks",gson.toJsonTree(blocks));item.add("edges",gson.toJsonTree(edges));item.add("options",gson.toJsonTree(options));item.add("specification",gson.toJsonTree(specification));item.add("fit",gson.toJsonTree(fit));if(scenario==0){JsonObject source=new JsonObject();source.add("observations",gson.toJsonTree(data));source.add("blocks",gson.toJsonTree(blocks));source.add("edges",gson.toJsonTree(edges));source.add("options",gson.toJsonTree(options));var derived=org.brightstats.data.HigherOrderProjects.create(source,fit);check(derived.getAsJsonArray("columnNames").size()==width+blocks.size());check(org.brightstats.data.ProjectDerivation.validate(derived.get("derivation"),width+blocks.size())!=null);var again=PlsSem.fit(new Gson().fromJson(derived.get("observations"),double[][].class),org.brightstats.data.PlsModelInput.blocks(derived.get("blocks")),org.brightstats.data.PlsModelInput.edges(derived.get("edges")),org.brightstats.data.PlsModelInput.options(derived.get("options")));for(var edge:secondEdges)check(again.pathCoefficients()[edge.source()][edge.target()]==fit.secondStage().pathCoefficients()[edge.source()][edge.target()]);JsonObject numeric=new JsonObject();numeric.add("higherOrderPls",gson.toJsonTree(fit));var archive=org.brightstats.report.ReportArchive.create("HOC_TEST",source,numeric,new JsonArray(),List.of());check(Double.isNaN(org.brightstats.report.HigherOrderReports.point(archive).firstStage().rSquared()[0]));var derivedArchive=org.brightstats.report.ReportArchive.create("DERIVED_TEST",derived,new JsonObject(),new JsonArray(),List.of());check(derivedArchive.getAsJsonArray("warnings").toString().contains("first-stage estimation uncertainty"));var bad=derived.getAsJsonObject("derivation").deepCopy();bad.addProperty("sourceSha256","bad");reject(()->org.brightstats.data.ProjectDerivation.validate(bad,width+blocks.size()));}
            if(scenario==0||scenario==1||scenario==3||scenario==4||scenario==5||scenario==8||scenario>=10){var settings=new Bootstrap.Options(40,345,.95,scenario==1?BootstrapIntervals.Method.BCA:BootstrapIntervals.Method.PERCENTILE,RegressionBootstrap.Convention.STANDARD,true);var result=HigherOrderPls.bootstrap(data,blocks,edges,options,specification,settings,null);check(result.inference().successful()==40&&result.inference().failed()==0);check(result.inference().signHandling().contains("aligns their signs before augmentation"));if(scenario!=8)check(result.inference().estimates().stream().anyMatch(value->value.parameter().family().equals("Specific indirect effect")));item.add("bootstrapOptions",gson.toJsonTree(settings));item.add("bootstrap",gson.toJsonTree(result.inference()));}cases.add(item);
        }
        var blocks=List.of(new PlsSem.Block("A",new int[]{0},PlsSem.Mode.A),new PlsSem.Block("B",new int[]{1},PlsSem.Mode.A),new PlsSem.Block("Y",new int[]{2},PlsSem.Mode.A));var edges=List.of(new PlsSem.Edge(0,2),new PlsSem.Edge(1,2));var dimension=new HigherOrderPls.Dimension("General",new int[]{0,1},PlsSem.Mode.A,PlsSem.MeasurementType.REFLECTIVE,null);var valid=new HigherOrderPls.Specification(new int[]{2},List.of(dimension),List.of(new PlsSem.Edge(1,0)),PlsSem.Options.defaults());
        reject(()->new HigherOrderPls.Dimension("Bad",new int[]{0,0},PlsSem.Mode.A,PlsSem.MeasurementType.REFLECTIVE,null));reject(()->new HigherOrderPls.Dimension("Bad",new int[]{0,1},PlsSem.Mode.A,PlsSem.MeasurementType.REFLECTIVE,new double[]{0,0}));reject(()->HigherOrderPls.validate(3,blocks,edges,new HigherOrderPls.Specification(new int[]{0,2},List.of(dimension),List.of(),PlsSem.Options.defaults())));reject(()->HigherOrderPls.validate(3,blocks,edges,new HigherOrderPls.Specification(new int[]{2},List.of(new HigherOrderPls.Dimension("A",new int[]{0,1},PlsSem.Mode.A,PlsSem.MeasurementType.REFLECTIVE,null)),List.of(),PlsSem.Options.defaults())));reject(()->HigherOrderPls.validate(3,blocks,edges,new HigherOrderPls.Specification(new int[]{2},List.of(dimension),List.of(new PlsSem.Edge(0,1),new PlsSem.Edge(1,0)),PlsSem.Options.defaults())));
        Thread.currentThread().interrupt();try{HigherOrderPls.fit(new double[][]{{1,2,3},{2,4,5},{3,1,2},{4,3,6}},blocks,edges,PlsSem.Options.defaults(),valid);throw new AssertionError("Higher-order fit ignored cancellation");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        Files.writeString(output.resolve("cases.json"),gson.toJson(cases));Files.writeString(output.resolve("checks.json"),"{\"cases\":"+cases.size()+",\"checks\":"+checks+"}");System.out.println("{\"cases\":"+cases.size()+",\"checks\":"+checks+"}");
    }
}
